  var __etNext = (function () { try { var n = new URLSearchParams(location.search).get('next'); return (n && n.charAt(0) === '/' && n.charAt(1) !== '/') ? n : '/'; } catch (e) { return '/'; } })();
  var cfg = window.EDIT_TIMELINE_FIREBASE;
